const portfolioFinancialDataDiscountRateDefault = 0;
const portfolioFinancialDataInflationRateDefault = 0;
const portfolioFinancialDataInterestRateDefault = 0;
export const PortfolioFinancialData = zod
  .object({
    id: zod.int().describe("ID for individual component."),
    discount_rate: zod
      .number()
      .default(portfolioFinancialDataDiscountRateDefault)
      .describe("Discount rate for financial calculations. Units: 1."),
    inflation_rate: zod
      .number()
      .default(portfolioFinancialDataInflationRateDefault)
      .describe("Inflation rate for cost adjustments. Units: 1."),
    interest_rate: zod
      .number()
      .default(portfolioFinancialDataInterestRateDefault)
      .describe("Interest rate for financing calculations. Units: 1."),
    base_year: zod
      .int()
      .describe(
        "Base economic year. All costs will be converted to a net present value in this year.",
      ),
  })
  .describe(
    "Financial data for the portfolio as a whole: the base economic year that all costs are converted to a net present value in, and the discount, inflation, and interest rates used in that conversion.",
  );

export type PortfolioFinancialData = zod.input<typeof PortfolioFinancialData>;
export type PortfolioFinancialDataOutput = zod.output<
  typeof PortfolioFinancialData
>;

export const RequirementAssociation = zod
  .object({
    requirement_id: zod
      .int()
      .describe("ID of the policy requirement the membership belongs to."),
    entity_id: zod
      .int()
      .describe("ID of the member the requirement applies to."),
  })
  .describe(
    "Links a policy requirement to one member subject to it. One record per (requirement, member) pair: the many-to-many relation between a requirement and the components it constrains is normalized here rather than carried as a list on either side, so each membership is an individually addressable row. The type of either side is resolved through the entity registry rather than duplicated here, matching the shape of SupplementalAttributeAssociation. `requirement_id` names the policy requirement (a CapacityReserveMargin, CarbonCap, EnergyShareRequirement, ...); `entity_id` names the member the requirement applies to, so no member-type discriminator is needed.",
  );

export type RequirementAssociation = zod.input<typeof RequirementAssociation>;
export type RequirementAssociationOutput = zod.output<
  typeof RequirementAssociation
>;

